/**
 * Estimated percentile (UI/app). There is no backend in the slice, so "Top 18% est." is read off a bot
 * population distribution of daily-best survival times and is ALWAYS labelled as an estimate in the UI.
 *
 * PLACEHOLDER table: spec 7.5 balance-sim results (8,000-player tiered population, daily best): p10 4:20,
 * p50 6:31, p90 8:51, p99 11:08; p25/p75 interpolated from the tier medians (casual 5:08, average 7:23,
 * good 8:47); the low tail from the skeptic's bimodal run (6% at the L2 boss). The game now uses the real-engine bot
 * distribution (bot/population.ts, generated by scripts/delve-pop.ts --write-table: tiered kiting bots on the real sim,
 * a BOT-POPULATION ESTIMATE, not player data); the spec table is kept as SPEC_SIM_POPULATION.
 */
import { BOT_POPULATION } from '../bot/population';

export interface Population {
  source: string;
  /** [percentile 0..100, seconds] ascending in both. */
  quantiles: readonly (readonly [number, number])[];
}

/** The spec 7.5 macro-sim table (kept for comparison and tests). */
export const SPEC_SIM_POPULATION: Population = {
  source: 'balance sim v1 (tiered 8,000)',
  quantiles: [[0, 30], [1, 95], [5, 170], [10, 260], [25, 318], [50, 391], [75, 452], [90, 531], [95, 580], [99, 668], [99.9, 760], [100, 872]],
};

/** What the game shows: the real-engine bot-population estimate (scripts/delve-pop.ts). */
export const POPULATION: Population = BOT_POPULATION;

/** Share of the population this run beats (0..100). */
export function estimatePercentile(sec: number, pop: Population = POPULATION): number {
  const q = pop.quantiles;
  if (sec <= q[0][1]) return 0;
  if (sec >= q[q.length - 1][1]) return 100;
  for (let i = 1; i < q.length; i++) {
    if (sec < q[i][1]) {
      const [p0, s0] = q[i - 1];
      const [p1, s1] = q[i];
      return p0 + ((p1 - p0) * (sec - s0)) / (s1 - s0);
    }
  }
  return 100;
}

/** The "Top N%" number (rounded up, 1 decimal under 1%, floor 0.1). */
export function topPercent(sec: number, pop: Population = POPULATION): number {
  const top = Math.max(0.1, 100 - estimatePercentile(sec, pop));
  return top < 1 ? Math.ceil(top * 10) / 10 : Math.min(99, Math.ceil(top));
}

/**
 * The rank line. "Top 18% est." only in the top half; below the median "Top 99%" reads as either "bottom 1%" or
 * "excellent" (QA), so it becomes "Beat 12% of bot runs (est.)".
 */
export function topLabel(sec: number, pop: Population = POPULATION): string {
  const t = topPercent(sec, pop);
  if (t <= 50) return `Top ${t < 1 ? t.toFixed(1) : String(t)}% est.`;
  const beat = Math.floor(estimatePercentile(sec, pop));
  return beat < 1 ? 'Beat <1% of bot runs (est.)' : `Beat ${beat}% of bot runs (est.)`;
}

/** How deep a run got: "Reached Layer 3" / "Reached the Core" / "Faced the Wyrm". */
export function milestoneLabel(sec: number): string {
  if (sec >= 720) return 'Faced the Wyrm';
  if (sec >= 300) return 'Reached the Core';
  return `Reached Layer ${Math.min(5, Math.floor(sec / 60) + 1)}`;
}

/** What the share text shows: the estimated rank in the top half, otherwise a depth milestone (no "Top 99%"). */
export function shareRank(sec: number, pop: Population = POPULATION): string {
  return topPercent(sec, pop) <= 50 ? topLabel(sec, pop) : milestoneLabel(sec);
}
